(function(){const palette=["#2ec7c9","#b6a2de","#5ab1ef","#ffb980","#d87a80","#8d98b3","#e5cf0d","#97b552","#95706d","#dc69aa","#07a2a4","#9a7fd1","#588dd5","#f5994e","#c05050","#59678c","#c9ab00","#76933c","#bc65a6"];const regionColors={MENAR:"#5ab1ef",ESAR:"#2ec7c9",ECAR:"#b6a2de",WCAR:"#ffb980",LACR:"#97b552",EAPR:"#d87a80",SAR:"#e5cf0d"};function getStableColor(name){if(!name)return"#5470c6";let hash=0;for(let i=0;i<name.length;i++){hash=name.charCodeAt(i)+(Math.imul(hash,32)-hash)}return palette[Math.abs(hash)%palette.length]}function getRegionColor(code){return regionColors[code]||getStableColor(code)}function timeAxisLabel(value){return d3.timeFormat("%b %y")(new Date(value))}function setDataAsOf(rows){const el=document.getElementById("data-as-of");if(!el)return;const dates=(rows||[]).map(row=>row&&row.date instanceof Date?row.date:new Date(row&&row.date)).filter(date=>!Number.isNaN(date.getTime()));if(dates.length===0){el.textContent="—";return}const latest=new Date(Math.max(...dates.map(date=>date.getTime())));el.textContent=d3.timeFormat("%d %b %Y")(latest)}window.HopeChart={palette:palette,regionColors:regionColors,getStableColor:getStableColor,getRegionColor:getRegionColor,timeAxisLabel:timeAxisLabel,setDataAsOf:setDataAsOf}})();
